export default {
  async fetch(request) {
    const requestUrl = new URL(request.url);
    if (requestUrl.pathname !== '/fetch-policy') {
      return Response.json({
        endpoint: '/fetch-policy?target=<absolute-url>',
        note: 'The Rust host owns the outbound policy; this Worker can only request a target.',
      }, { status: 404 });
    }

    const target = requestUrl.searchParams.get('target');
    if (target === null) {
      return Response.json({ outcome: 'invalid', message: 'target query parameter is required' }, { status: 400 });
    }

    try {
      const response = await fetch(target, { redirect: 'manual' });
      return Response.json({
        outcome: 'success',
        target,
        status: response.status,
        location: response.headers.get('location'),
        body: await response.text(),
      });
    } catch (error) {
      return Response.json({
        outcome: 'error',
        target,
        error: {
          name: error?.name ?? 'Error',
          message: error?.message ?? String(error),
        },
      });
    }
  },
};
